import * as T from './three.js';
import {clipCamera} from './experience.js';
export const CINEMA_SHOTS={orbit:'Slow orbit',tracking:'Tracking profile',overhead:'Overhead survey'};
export function fleetFrame(drones){if(!drones.length)return null;const min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];for(const d of drones){const p=d.system?.pos||d.pos;for(let i=0;i<3;i++){min[i]=Math.min(min[i],p[i]);max[i]=Math.max(max[i],p[i]);}}return {center:min.map((v,i)=>(v+max[i])/2),radius:Math.max(10,Math.hypot(...max.map((v,i)=>(v-min[i])/2)))};}
export class CinematicCamera{
 constructor(){this.active=false;this.shot='orbit';this.subject='rig';this.distance=18;this.speed=.12;this.time=0;this.owner=null;this.position=new T.Vector3();this.identity='';}
 start(state){this.active=true;this.owner=state;this.time=0;this.identity='';}
 stop(){this.active=false;this.owner=null;this.identity='';}
 update(camera,state,{bike,trail,fleet,solids,ground,dt=0,paused=false,reducedMotion=false}){
  if(!this.active)return false;if(this.owner!==state||state.dead){this.stop();return false;}if(!paused)this.time+=dt;
  const frame=this.subject==='fleet'?fleetFrame(fleet?.drones||[]):null;
  const target=frame?.center||(this.subject==='player'?state.pos.toArray():[bike.position.x,bike.position.y+1.2,bike.position.z]);
  const halfFov=Math.atan(Math.tan(42*Math.PI/360)*Math.min(1,camera.aspect)),fit=frame?frame.radius/Math.sin(halfFov)*1.15:this.distance,angle=state.yaw+(reducedMotion?-.6:this.shot==='orbit'?this.time*this.speed:-1.05);
  const desired=this.shot==='overhead'?[target[0],target[1]+fit*1.35,target[2]+.01]:[target[0]+Math.sin(angle)*fit,target[1]+fit*.32,target[2]+Math.cos(angle)*fit];desired[1]=Math.max(ground(desired[0],desired[2])+1.5,desired[1]);
  const safe=clipCamera(target,desired,solids),identity=this.subject+this.shot+camera.aspect;if(identity!==this.identity||reducedMotion)this.position.fromArray(safe);else this.position.lerp(new T.Vector3().fromArray(safe),1-Math.exp(-Math.max(dt,.001)*3));this.identity=identity;camera.position.fromArray(clipCamera(target,this.position.toArray(),solids));camera.lookAt(new T.Vector3().fromArray(target));camera.fov=42;camera.far=Math.max(3500,fit+(frame?.radius||0)*2);camera.updateProjectionMatrix();camera.updateMatrixWorld();return true;
 }
}
export function cinemaPanel(cinema,{started=false,fleet=false}={}){return `<section class="cinemaPanel"><div class="panelTop"><div><span class="eyebrow">LIVE CAMERA / F8</span><h2>Cinematic camera</h2></div><button data-back>← Back</button></div><p>Compose a shot of the live world. Your fleet keeps flying; the camera does not drive the bike. F8 or Exit cinematic returns to your normal view.</p><label>Subject<select data-cinema-setting="subject"><option value="rig" ${cinema.subject==='rig'?'selected':''}>Bike & trailer</option><option value="player" ${cinema.subject==='player'?'selected':''}>Player / current aircraft</option><option value="fleet" ${cinema.subject==='fleet'?'selected':''} ${fleet?'':'disabled'}>Whole test fleet / staging grid</option></select></label><label>Shot<select data-cinema-setting="shot">${Object.entries(CINEMA_SHOTS).map(([id,label])=>`<option value="${id}" ${cinema.shot===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Rig / player distance<input data-cinema-setting="distance" type="range" min="6" max="70" step="1" value="${cinema.distance}"></label><label>Orbit speed<input data-cinema-setting="speed" type="range" min="0" max=".3" step=".01" value="${cinema.speed}"></label><p>Fleet shots frame all deployed aircraft automatically, including those on the ground. Buildings can constrain the view. Reduced motion holds the camera angle steady.</p><button class="primary" data-cinema-start ${started?'':'disabled'}>START CINEMATIC & RESUME</button><button data-nav="environment">LIGHT & WEATHER</button><button data-learning-jump="cinema">CAMERA TUTORIAL</button></section>`;}
